import { loadFont } from "@remotion/google-fonts/Arimo";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// ACADEMIA FALCON (cliente Josiane/Josilane) — v2 "mais motion" (pedido, 25/10): mesma voz e mesma identidade
// da v1 (FalconMulher.tsx), agora intercalando vídeo da piscina e cenas desenhadas: abertura OUTUBRO em batida, presente
// abrindo, ícones de saúde e disposição, calendário do plano anual, selo 2X, preço, cronômetro do tempo limitado e logo.
// Identidade dos vídeos anteriores da Falcon: preto, vermelho e branco, Arimo itálico caixa-alta, palavra-chave numa
// tarja branca inclinada, faixas diagonais vermelhas. Tempos = tempos da voz (src/voz-v1.mp3, o locutor), que começa em 0.

const { fontFamily: FI } = loadFont("italic", { weights: ["700"], subsets: ["latin", "latin-ext"] });

export const FM2_FPS = 30;
const FM_FPS = FM2_FPS;
const END = 36.6;
export const FM2_FRAMES = Math.round(END * FM_FPS);
const RED = "#D4000F";
const DARK_RED = "#5C0009";
const WHITE = "#FFFFFF";
const INK = "#0B0B0B";
const GREEN = "#25D366";
const COL = 840; // coluna de texto (margem de 120 em 1080)

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.5));
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const it = (size: number, color = WHITE): React.CSSProperties => ({ fontFamily: FI, fontStyle: "italic", fontWeight: 700, fontSize: size, lineHeight: 1, color, textTransform: "uppercase", whiteSpace: "nowrap", letterSpacing: "-0.01em" });

// ───────── vídeos em tela cheia ─────────
// entrada de cada vídeo; nunca a mesma duas vezes seguidas
type In = "flash" | "stripe" | "punch" | "slideL" | "slideR" | "cut";
type Seg = { a: number; b: number; src: string; from: number; zin?: boolean; x?: number; enter: In };
const SEGS: Seg[] = [
  { a: 1.4, b: 3.05, src: "h1", from: 2.0, enter: "cut" },
  { a: 4.42, b: 6.05, src: "p4", from: 0.5, enter: "punch", zin: true },
  { a: 9.75, b: 12.24, src: "h4", from: 1.5, enter: "cut", zin: true },
  { a: 14.05, b: 15.28, src: "n1", from: 2.4, enter: "punch" },
  { a: 15.28, b: 16.8, src: "h1", from: 9.0, enter: "slideR", zin: true },
  { a: 16.8, b: 18.22, src: "p3", from: 1.0, enter: "flash" },
  { a: 22.62, b: 24.9, src: "h2", from: 3.0, enter: "cut", zin: true },
  { a: 26.68, b: 29.55, src: "h1", from: 13.0, enter: "cut" },
  { a: 29.55, b: 32.24, src: "p5", from: 3.4, enter: "slideL", zin: true },
];
// cenas desenhadas (o vídeo aparece fora delas)
const MS = { hook: [0, 1.4], gift: [3.05, 4.42], bem: [6.05, 9.75], ano: [12.24, 14.05], price: [18.22, 22.62], timer: [24.9, 26.68] } as const;
const PRICE = { a: MS.price[0], b: MS.price[1] };
const inM = (t: number) => Object.values(MS).some(([a, b]) => t >= a && t < b);
const FIM = 32.24;

const Clip: React.FC<{ t: number; s: Seg }> = ({ t, s }) => {
  const tail = 0.3; // o vídeo anterior continua por baixo enquanto o próximo entra
  if (t < s.a - 0.01 || t > s.b + tail) return null;
  const u = lin(t, s.a, s.b + tail);
  const z = s.zin ? 1.04 + 0.1 * u : 1.15 - 0.09 * u;
  let tx = 0;
  let extra = 1;
  if (s.enter === "slideL" || s.enter === "slideR") tx = (1 - k(t, s.a, 0.32)) * 1080 * (s.enter === "slideL" ? 1 : -1);
  if (s.enter === "punch") extra = 1 + 0.28 * (1 - k(t, s.a, 0.3));
  return (
    <AbsoluteFill style={{ transform: `translateX(${tx.toFixed(1)}px)`, overflow: "hidden", background: "#000" }}>
      <Sequence from={Math.round(s.a * FM_FPS)} layout="none">
        <OffthreadVideo src={staticFile(`josiane/${s.src}.mp4`)} trimBefore={Math.round(s.from * FM_FPS)} muted style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${(z * extra).toFixed(4)})` }} />
      </Sequence>
    </AbsoluteFill>
  );
};
// clarão branco e faixa diagonal vermelha nas trocas
const Flash: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  if (t < at || t > at + 0.25) return null;
  return <AbsoluteFill style={{ background: WHITE, opacity: 0.85 * (1 - lin(t, at, at + 0.25)) }} />;
};
const Stripe: React.FC<{ t: number; at: number; i: number }> = ({ t, at, i }) => {
  const d = 0.2;
  if (t < at - d || t > at + d) return null;
  const dir = i % 2 ? -1 : 1;
  const x = (lin(t, at - d, at + d) * 2 - 1) * 2100 * dir;
  return (
    <div style={{ position: "absolute", left: 540 - 800, top: -300, width: 1600, height: 2520, transform: `translateX(${x.toFixed(0)}px) skewX(${-16 * dir}deg)`, background: RED, boxShadow: `${110 * dir}px 0 0 ${WHITE}, ${-110 * dir}px 0 0 ${DARK_RED}` }} />
  );
};

// ───────── lettering: cada frase no mesmo lugar; a anterior some inteira antes de a próxima entrar ─────────
type Ln = { w: string; at: number; tag?: boolean; size?: number };
type Phrase = { lines: Ln[]; out: number; heart?: number; badge?: number };
const PH: Phrase[] = [
  { lines: [{ w: "A Academia Falcon", at: 1.4 }, { w: "Preparou", at: 2.55, tag: true }], out: 2.85 },
  { lines: [{ w: "Para você,", at: 4.45 }, { w: "Mulher!", at: 5.13, tag: true, size: 120 }], out: 5.85, heart: 5.13 },
  { lines: [{ w: "Ter mais", at: 9.78 }, { w: "Qualidade de vida", at: 10.62, tag: true }], out: 12.04 },
  { lines: [{ w: "Natação", at: 14.1 }, { w: "Adulto", at: 14.66, tag: true, size: 120 }], out: 15.1 },
  { lines: [{ w: "ou", at: 15.3 }, { w: "Hidroginástica", at: 15.42, tag: true }], out: 16.3 },
  { lines: [{ w: "Duas vezes", at: 16.48 }, { w: "Por semana", at: 17.16, tag: true }], out: 18.02, badge: 16.48 },
  { lines: [{ w: "Mas", at: 22.66 }, { w: "Corra!", at: 22.98, tag: true, size: 130 }], out: 24.7 },
  { lines: [{ w: "Garanta sua", at: 29.58 }, { w: "Condição especial", at: 30.43, tag: true }], out: 32.04 },
];
const outOf = (i: number) => PH[i].out;
const fit = (l: Ln) => l.size ?? Math.min(l.tag ? 112 : 70, Math.floor((COL - (l.tag ? 80 : 0)) / (l.w.length * (l.tag ? 0.6 : 0.56))));

const Heart: React.FC<{ s: number; c?: string }> = ({ s, c = RED }) => (
  <svg width={s} height={s} viewBox="0 0 24 24"><path d="M12 21s-7.5-4.6-10-9.3C.4 8.4 2.3 4.5 6 4.5c2.2 0 3.5 1.2 4.3 2.4h3.4C14.5 5.7 15.8 4.5 18 4.5c3.7 0 5.6 3.9 4 7.2C19.5 16.4 12 21 12 21z" fill={c} /></svg>
);

const Lettering: React.FC<{ t: number }> = ({ t }) => (
  <>
    {PH.map((p, i) => {
      const first = p.lines[0].at;
      const out = outOf(i);
      if (t < first - 0.02 || t > out + 0.18) return null;
      const o = lin(t, out, out + 0.16);
      return (
        <div key={i} style={{ position: "absolute", left: 0, right: 0, top: 1300, height: 330, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 18, opacity: 1 - o }}>
          {p.badge !== undefined ? (
            <div style={{ position: "absolute", top: -250, left: 0, right: 0, display: "flex", justifyContent: "center", transform: `scale(${pop(t, p.badge, 0.5).toFixed(3)}) rotate(${(-8 + 8 * k(t, p.badge, 0.6)).toFixed(1)}deg)` }}>
              <div style={{ width: 210, height: 210, borderRadius: "50%", background: RED, border: `8px solid ${WHITE}`, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 18px 40px rgba(0,0,0,0.5)" }}>
                <div style={{ ...it(110), marginLeft: -8 }}>2X</div>
              </div>
            </div>
          ) : null}
          {p.heart !== undefined ? (
            <div style={{ position: "absolute", top: -96, left: 0, right: 0, display: "flex", justifyContent: "center", transform: `scale(${pop(t, p.heart, 0.5).toFixed(3)})` }}>
              <Heart s={96} />
            </div>
          ) : null}
          {p.lines.map((l, j) => {
            const s = fit(l);
            if (!l.tag) {
              const e = k(t, l.at, 0.4);
              return <div key={j} style={{ ...it(s), textShadow: "0 4px 18px rgba(0,0,0,0.7)", opacity: Math.min(1, e * 2), transform: `translateX(${((1 - e) * -120).toFixed(1)}px)` }}>{l.w}</div>;
            }
            const e = k(t, l.at, 0.42);
            const tx = interpolate(t, [l.at + 0.08, l.at + 0.36], [0, 1], { ...cl, easing: OUT });
            return (
              <div key={j} style={{ background: WHITE, padding: `${s * 0.12}px ${s * 0.36}px ${s * 0.18}px`, transform: `skewX(-10deg) scaleX(${e.toFixed(3)})`, boxShadow: `0 16px 40px rgba(0,0,0,0.45), 12px 12px 0 ${RED}` }}>
                <div style={{ ...it(s, RED), transform: "skewX(10deg)", opacity: tx }}>{l.w}</div>
              </div>
            );
          })}
        </div>
      );
    })}
  </>
);

// ───────── WhatsApp (26.71–29.5) ─────────
const WaIcon: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 32 32"><path fill={WHITE} d="M16 3C9 3 3.3 8.6 3.3 15.6c0 2.4.7 4.7 1.9 6.7L3 29l6.9-2.2c1.9 1 4 1.6 6.1 1.6 7 0 12.7-5.7 12.7-12.7S23 3 16 3zm0 23.2c-2 0-3.9-.6-5.5-1.6l-.4-.2-4.1 1.3 1.3-4-.3-.4c-1.1-1.7-1.7-3.6-1.7-5.6C5.3 9.8 10.1 5.1 16 5.1s10.7 4.7 10.7 10.6S21.9 26.2 16 26.2zm5.9-7.9c-.3-.2-1.9-1-2.2-1.1-.3-.1-.5-.2-.7.2-.2.3-.8 1-1 1.2-.2.2-.4.2-.7.1-.3-.2-1.4-.5-2.6-1.6-1-.9-1.6-1.9-1.8-2.2-.2-.3 0-.5.1-.7l.5-.6c.2-.2.2-.3.3-.6.1-.2 0-.4 0-.6l-1-2.4c-.3-.6-.5-.5-.7-.5h-.6c-.2 0-.6.1-.9.4-.3.3-1.2 1.1-1.2 2.8 0 1.6 1.2 3.2 1.4 3.4.2.2 2.3 3.6 5.7 5 .8.3 1.4.5 1.9.7.8.3 1.5.2 2.1.1.6-.1 1.9-.8 2.2-1.5.3-.7.3-1.4.2-1.5-.1-.2-.3-.3-.6-.4z" /></svg>
);
const Whats: React.FC<{ t: number }> = ({ t }) => {
  const a = 26.71, b = 29.4;
  if (t < a - 0.02 || t > b + 0.2) return null;
  const o = lin(t, b, b + 0.16);
  const press = 1 - 0.08 * Math.max(0, 1 - Math.abs(t - 27.45) / 0.12);
  const ring = lin(t, 27.45, 28.1);
  const sub = k(t, 28.18, 0.4);
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top: 1290, height: 360, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 30, opacity: 1 - o }}>
      <div style={{ position: "relative", transform: `scale(${(pop(t, a, 0.5) * press).toFixed(3)})` }}>
        {t > 27.45 ? <div style={{ position: "absolute", inset: 0, borderRadius: 999, border: `6px solid ${GREEN}`, opacity: 1 - ring, transform: `scale(${(1 + ring * 0.35).toFixed(3)})` }} /> : null}
        <div style={{ display: "flex", alignItems: "center", gap: 22, background: GREEN, borderRadius: 999, padding: "24px 46px 26px 34px", boxShadow: "0 18px 44px rgba(0,0,0,0.5)" }}>
          <WaIcon s={70} />
          <div style={it(56)}>Clique no WhatsApp</div>
        </div>
      </div>
      <div style={{ ...it(62), textShadow: "0 4px 18px rgba(0,0,0,0.7)", opacity: Math.min(1, sub * 2), transform: `translateY(${((1 - sub) * 40).toFixed(1)}px)` }}>Fale com nossa equipe</div>
    </div>
  );
};

// ───────── fundo das cenas de motion: preto com faixas diagonais vermelhas ─────────
const Stripes: React.FC<{ t: number }> = ({ t }) => {
  const d = Math.sin(t * 0.6) * 50;
  return (
    <AbsoluteFill style={{ background: "linear-gradient(170deg, #0A0A0A 0%, #12060A 55%, #2A0006 100%)", overflow: "hidden" }}>
      {[
        [760, 260, RED, 1],
        [520, 120, DARK_RED, 0.9],
        [1040, 300, "#8E000C", 0.55],
        [-120, 180, DARK_RED, 0.6],
      ].map(([x, w, col, op], i) => (
        <div key={i} style={{ position: "absolute", left: (x as number) + d * (i % 2 ? 1 : -1), top: -300, width: w as number, height: 2600, background: col as string, opacity: op as number, transform: "skewX(-24deg)", overflow: "hidden" }}>
          <div style={{ position: "absolute", left: 0, right: 0, height: 700, top: -700 + ((t * (0.3 + i * 0.06) + i * 0.31) % 1) * 3300, background: "linear-gradient(180deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.3) 50%, rgba(255,255,255,0) 100%)" }} />
        </div>
      ))}
    </AbsoluteFill>
  );
};

// ───────── preço (18.22–22.62) ─────────
const Price: React.FC<{ t: number }> = ({ t }) => {
  const { a, b } = PRICE;
  if (t < a || t >= b + 0.01) return null;
  const cam = 1 + 0.05 * lin(t, a, b);
  const big = k(t, 19.78, 0.32);
  return (
    <AbsoluteFill>
      <Stripes t={t} />
      <AbsoluteFill style={{ transform: `scale(${cam.toFixed(4)}) translateY(${(Math.sin(t * 1.4) * 8).toFixed(1)}px)`, transformOrigin: "50% 45%" }}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 360, display: "flex", justifyContent: "center", gap: 24 }}>
          {[["Plano anual", a + 0.1], ["2x por semana", a + 0.3]].map(([w, at]) => (
            <div key={w as string} style={{ ...it(40, WHITE), border: `4px solid ${WHITE}`, borderRadius: 14, padding: "12px 24px 14px", opacity: k(t, at as number, 0.3), transform: `translateY(${((1 - k(t, at as number, 0.35)) * -40).toFixed(1)}px)` }}>{w}</div>
          ))}
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 560, display: "flex", justifyContent: "center", ...{ opacity: k(t, 18.22, 0.3), transform: `translateX(${((1 - k(t, 18.22, 0.4)) * -140).toFixed(1)}px)` } }}>
          <div style={it(92)}>Por apenas</div>
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 720, display: "flex", justifyContent: "center", alignItems: "flex-start", gap: 14, opacity: t >= 19.78 ? Math.min(1, big * 3) : 0, transform: `scale(${(1.6 - 0.6 * big).toFixed(3)})` }}>
          <div style={{ ...it(96), marginTop: 40, textShadow: `5px 5px 0 ${INK}` }}>R$</div>
          <div style={{ ...it(280), letterSpacing: "-0.04em", textShadow: `8px 8px 0 ${INK}, 0 0 50px rgba(0,0,0,0.55)` }}>99,90</div>
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 1110, display: "flex", justifyContent: "center" }}>
          <div style={{ background: WHITE, padding: "14px 46px 20px", transform: `skewX(-10deg) scaleX(${k(t, 21.42, 0.4).toFixed(3)})`, boxShadow: `12px 12px 0 ${RED}` }}>
            <div style={{ ...it(96, RED), transform: "skewX(10deg)", opacity: lin(t, 21.5, 21.75) }}>por mês</div>
          </div>
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 1340, display: "flex", justifyContent: "center", gap: 26 }}>
          {[["Natação adulto", 20.6], ["Hidroginástica", 20.85]].map(([w, at]) => (
            <div key={w as string} style={{ ...it(38, INK), background: WHITE, borderRadius: 999, padding: "14px 28px 16px", transform: `scale(${pop(t, at as number, 0.4).toFixed(3)})` }}>{w}</div>
          ))}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── encerramento (32.24–fim) ─────────
const Fim: React.FC<{ t: number }> = ({ t }) => {
  if (t < FIM) return null;
  const e = pop(t, FIM + 0.05, 0.6);
  return (
    <AbsoluteFill>
      <Stripes t={t} />
      <AbsoluteFill style={{ transform: `scale(${(1 + 0.04 * lin(t, FIM, END)).toFixed(4)})` }}>
        <div style={{ position: "absolute", left: 90, right: 90, top: 520, height: 560, borderRadius: "50%", background: "radial-gradient(ellipse at center, rgba(0,0,0,0.92) 0%, rgba(0,0,0,0.75) 45%, rgba(0,0,0,0) 72%)", opacity: Math.min(1, e * 2) }} />
        <div style={{ position: "absolute", left: 0, right: 0, top: 650, display: "flex", justifyContent: "center", opacity: Math.min(1, e * 2), transform: `scale(${e.toFixed(3)})` }}>
          <Img src={staticFile("josiane/logo-completo.png")} style={{ width: 860, display: "block", filter: "drop-shadow(0 18px 40px rgba(0,0,0,0.6))" }} />
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 1060, display: "flex", justifyContent: "center" }}>
          <div style={{ background: WHITE, padding: "16px 48px 22px", transform: `skewX(-10deg) scaleX(${k(t, 33.48, 0.45).toFixed(3)})`, boxShadow: `12px 12px 0 ${RED}` }}>
            <div style={{ ...it(68, RED), transform: "skewX(10deg)", opacity: lin(t, 33.56, 33.85) }}>Feita para a família!</div>
          </div>
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 1290, display: "flex", justifyContent: "center", transform: `scale(${pop(t, 34.6, 0.45).toFixed(3)})` }}>
          <div style={{ display: "flex", alignItems: "center", gap: 16, background: GREEN, borderRadius: 999, padding: "16px 40px 18px 28px" }}>
            <WaIcon s={58} />
            <div style={it(48)}>Chame no WhatsApp</div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── cenas desenhadas ─────────
type Cam = "in" | "out" | "left" | "right" | "tilt";
const RedBg: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: `linear-gradient(165deg, #F01020 0%, ${RED} 45%, #7A0008 100%)`, overflow: "hidden" }}>
    {[0, 1, 2].map((i) => (
      <div key={i} style={{ position: "absolute", left: -400 + i * 520 + ((t * 60) % 520), top: -300, width: 90 - i * 22, height: 2600, background: "rgba(255,255,255,0.10)", transform: "skewX(-24deg)" }} />
    ))}
    <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: 700, background: "linear-gradient(180deg, rgba(60,0,4,0) 0%, rgba(60,0,4,0.55) 100%)" }} />
  </AbsoluteFill>
);
const MScene: React.FC<{ t: number; a: number; b: number; bg: "dark" | "red"; cam: Cam; children: React.ReactNode }> = ({ t, a, b, bg, cam, children }) => {
  if (t < a || t >= b) return null;
  const u = lin(t, a, b);
  const e = interpolate(u, [0, 1], [0, 1], { easing: Easing.inOut(Easing.sin) });
  const sway = Math.sin((t - a) * 2.2);
  const tr =
    cam === "in" ? `scale(${(1 + 0.14 * e).toFixed(4)}) translateY(${(sway * 10).toFixed(1)}px)`
    : cam === "out" ? `scale(${(1.16 - 0.14 * e).toFixed(4)}) rotate(${(sway * 0.8).toFixed(2)}deg)`
    : cam === "left" ? `translateX(${(70 - 140 * e).toFixed(1)}px) scale(1.08)`
    : cam === "right" ? `translateX(${(-25 + 50 * e).toFixed(1)}px) scale(${(1.0 + 0.08 * e).toFixed(4)}) translateY(${(sway * 8).toFixed(1)}px)`
    : `rotate(${(-2.5 + 5 * e).toFixed(2)}deg) scale(${(1.06 + 0.06 * e).toFixed(4)})`;
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {bg === "dark" ? <Stripes t={t} /> : <RedBg t={t} />}
      <AbsoluteFill style={{ transform: tr, transformOrigin: "50% 45%" }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};
const Row: React.FC<{ top: number; children: React.ReactNode; gap?: number; style?: React.CSSProperties }> = ({ top, children, gap = 0, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", justifyContent: "center", alignItems: "center", gap, ...style }}>{children}</div>
);
const Tag: React.FC<{ t: number; at: number; w: string; size: number; shadow?: string }> = ({ t, at, w, size, shadow = RED }) => (
  <div style={{ background: WHITE, padding: `${size * 0.12}px ${size * 0.36}px ${size * 0.18}px`, transform: `skewX(-10deg) scaleX(${k(t, at, 0.42).toFixed(3)})`, boxShadow: `0 16px 40px rgba(0,0,0,0.35), 12px 12px 0 ${shadow}` }}>
    <div style={{ ...it(size, RED), transform: "skewX(10deg)", opacity: interpolate(t, [at + 0.08, at + 0.36], [0, 1], { ...cl, easing: OUT }) }}>{w}</div>
  </div>
);
const Line: React.FC<{ t: number; at: number; w: string; size: number }> = ({ t, at, w, size }) => {
  const e = k(t, at, 0.4);
